{
  "criteria": [
    {
      "kind": "exclusion",
      "text": "HER2 overexpressing (IHC3+ or IHC2+/ISH+) adenocarcinoma of breast, gastric or gastroesophageal junction as determined by local HER2 testing. Patients with breast, gastroesophageal and gastric cancer harboring selected specific HER2 activating mutations (See inclusion criteria 6) and who have received prior trastuzumab or other HER2 targeting therapy will be eligible if HER2 is not overexpressed (IHC3+ or IHC2+/ISH+) in a tissue biopsy taken after documented disease progression following trastuzumab and/or HER2 targeting treatment.",
      "quote": "HER2 overexpressing (IHC3+ or IHC2+/ISH+) adenocarcinoma of breast, gastric or gastroesophageal junction as determined by local HER2 testing.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "HER2 mutant NSCLC.",
      "quote": "HER2 mutant NSCLC.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with a medical history of myocardial infarction within 6 months before randomization/enrolment, symptomatic CHF (New York Heart Association Class II to IV), unstable angina pectoris, clinically important cardiac arrhythmias, or a recent (< 6 months) cardiovascular event including stroke. Patients with troponin levels above ULN at screening (as defined by the manufacturer), and without any myocardial infarction related symptoms, should have a cardiologic consultation before enrolment to rule out myocardial infarction.",
      "quote": "Patients with a medical history of myocardial infarction within 6 months before randomization/enrolment, symptomatic CHF (New York Heart Association Class II to IV), unstable angina pectoris, clinically important cardiac arrhythmias, or a recent (< 6 months) cardiovascular event including stroke.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Corrected QT interval by Fridericia's formula (QTcF) prolongation to > 470 msec (females) or > 450 msec (males) based on average of the screening triplicate 12-lead ECG.",
      "quote": "Corrected QT interval by Fridericia's formula (QTcF) prolongation to > 470 msec (females) or > 450 msec (males) based on average of the screening triplicate 12-lead ECG.",
      "thresholds": [
        {"test": "QTcF", "op": ">", "value": 470, "unit": "msec"},
        {"test": "QTcF", "op": ">", "value": 450, "unit": "msec"}
      ]
    },
    {
      "kind": "exclusion",
      "text": "Has a history of (non-infectious) interstitial lung disease (ILD)/pneumonitis that required steroids, has current ILD/pneumonitis, or where suspected ILD/pneumonitis cannot be ruled out by imaging at screening.",
      "quote": "Has a history of (non-infectious) interstitial lung disease (ILD)/pneumonitis that required steroids, has current ILD/pneumonitis, or where suspected ILD/pneumonitis cannot be ruled out by imaging at screening.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has a pleural effusion, ascites or pericardial effusion that requires drainage, peritoneal shunt, or Cell-free and Concentrated Ascites Reinfusion Therapy (CART). (Drainage and CART are not allowed within 2 weeks prior to screening assessment).",
      "quote": "Has a pleural effusion, ascites or pericardial effusion that requires drainage, peritoneal shunt, or Cell-free and Concentrated Ascites Reinfusion Therapy (CART).",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Active primary immunodeficiency, known HIV infection, or active hepatitis B or C infection. Patients positive for HCV antibody are eligible only if polymerase chain reaction is negative for HCV RNA. Patients should be tested for HIV prior to randomization/enrolment if required by local regulations or IRB/IEC.",
      "quote": "Active primary immunodeficiency, known HIV infection, or active hepatitis B or C infection.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Receipt of live, attenuated vaccine within 30 days prior to the first dose of T-DXd. Note: Patients, if enrolled, should not receive live vaccine during the study and up to 30 days after the last dose of IP.",
      "quote": "Receipt of live, attenuated vaccine within 30 days prior to the first dose of T-DXd.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has unresolved toxicities from previous anticancer therapy, defined as toxicities (other than alopecia) not yet resolved to Grade ≤ 1 or baseline. Patients with chronic Grade 2 toxicities may be eligible per the discretion of the Investigator after consultation with the Sponsor Medical Monitor or designee (eg, Grade 2 chemotherapy-induced neuropathy).",
      "quote": "Has unresolved toxicities from previous anticancer therapy, defined as toxicities (other than alopecia) not yet resolved to Grade ≤ 1 or baseline.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Lvef at or above 40 %. skin cancer, curatively treated in-situ disease, other solid tumors curatively treated, or contralateral breast cancer.",
      "quote": "Lvef at or above 40 %.",
      "thresholds": [
        {"test": "LVEF", "op": ">=", "value": 40, "unit": "%"}
      ]
    },
    {
      "kind": "exclusion",
      "text": "Known allergy or hypersensitivity to the IP or any of the study drug excipients.",
      "quote": "Known allergy or hypersensitivity to the IP or any of the study drug excipients.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Pregnant or breastfeeding female patients.",
      "quote": "Pregnant or breastfeeding female patients.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Uncontrolled infection requiring IV antibiotics, antivirals, or antifungals.",
      "quote": "Uncontrolled infection requiring IV antibiotics, antivirals, or antifungals.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Lung-specific intercurrent clinically significant illnesses including, but not limited to, any underlying pulmonary disorder (ie, pulmonary emboli within three months of the study enrolment, severe asthma, severe COPD, restrictive lung disease, pleural effusion etc), and any autoimmune, connective tissue or inflammatory disorders with documented or suspicious pulmonary involvement at screening (ie, rheumatoid arthritis, Sjogren's, sarcoidosis etc), and prior pneumonectomy.",
      "quote": "Lung-specific intercurrent clinically significant illnesses including, but not limited to, any underlying pulmonary disorder (ie, pulmonary emboli within three months of the study enrolment, severe asthma, severe COPD, restrictive lung disease, pleural effusion etc)",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Uncontrolled intercurrent illness, including but not limited to ongoing or active infection, uncontrolled hypertension, serious chronic gastrointestinal conditions associated with diarrhea, or psychiatric illness/social situations that would limit compliance with study requirement, substantially increase risk of incurring AEs, or compromise the ability of the patient to give written informed consent.",
      "quote": "Uncontrolled intercurrent illness, including but not limited to ongoing or active infection, uncontrolled hypertension, serious chronic gastrointestinal conditions associated with diarrhea, or psychiatric illness/social situations that would limit compliance with study requirement",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has spinal cord compression or clinically active central nervous system metastases, defined as untreated and symptomatic, or requiring therapy with corticosteroids or anticonvulsants to control associated symptoms. Patients with clinically inactive brain metastases may be included in the study. Patients with treated brain metastases that are no longer symptomatic and who require no treatment with corticosteroids or anticonvulsants may be included in the study if they have recovered from the acute toxic effect of radiotherapy. A minimum of 2 weeks must have elapsed between the end of whole brain radiotherapy and study enrolment.",
      "quote": "Has spinal cord compression or clinically active central nervous system metastases, defined as untreated and symptomatic, or requiring therapy with corticosteroids or anticonvulsants to control associated symptoms.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients participating in a concurrent interventional clinical study and/or previously treated with T-DXd.",
      "quote": "Patients participating in a concurrent interventional clinical study and/or previously treated with T-DXd.",
      "thresholds": []
    }
  ]
}
